        saved.running = false;
        saved.proposals.extend(settled);
        let none_waiting = saved.proposals.is_empty();
        if let Some(draft) = self.story_drafts.get_mut(name) {
            draft.proposed_nothing = proposed_nothing && none_waiting;
        }
        self.save_draft(name, cx);
        cx.notify();
    }

